function skipEmptySteps(){return G.skipEmptySteps(state);}
function scheduleAi(){if(aiMode!=='ai'||aiTimer||rolling||autoResolving||movementAnimating||!AI.shouldAct(state))return;aiTimer=setTimeout(runAiStep,650);}
function runAiStep(){aiTimer=null;if(aiMode!=='ai'||!AI.shouldAct(state))return;if($('rulesDialog').open||$('resetDialog').open||rolling||autoResolving||movementAnimating){aiTimer=setTimeout(runAiStep,650);return;}try{const out=AI.takeStep(state),decision=AI.humanDecision(state);ordersOpen=!!decision;rocketSelected=false;cannonSelected=null;if(decision)state.selected=decision.id;render();if(out.artillery)artilleryImpact(out.report,out.positions);else if(out.spell&&out.report?.effect?.unsaved)impactEffect(out.point,'volley',out.report.effect.unsaved);else if(out.report?.hits)impactEffect(out.point,'volley',out.report.unsaved);notify(decision?.message??out.message);}catch(e){aiMode='human';render();notify('AI stopped: '+e.message+'. Continue in two-player mode.',true);}}
function nextPhase(){safely(()=>{const before=state.stage,previous=state.selected;ordersOpen=false;rocketSelected=false;cannonSelected=null;if(state.stage==='deployment')G.begin(state);else if(state.stage==='movement'&&state.movementStep==='declare')G.finishDeclarations(state);else G.nextPhase(state);if(before!=='movement'||state.movementStep!=='declare')declinedCharges.clear();const skipped=skipEmptySteps();advanceSelection(previous);resetOrder();notify(`${skipped.length?skipped.join(', ')+' skipped: no eligible actions. ':''}${armyName(state.team)} · ${state.stage==='movement'?movementStepName():title(state.stage)}. ${state.stage==='combat'?'Select engaged regiments to fight.':state.stage==='movement'?'Choose a regiment for orders.':'Choose a unit to act.'}`);});}
