for(const [id,value]of [['forwardKind','advance'],['backKind','back'],['sideKind','side'],['wheelKind','wheel'],['pivotKind','pivot']])$(id).onclick=()=>{kind=value;if(kind==='advance')distance=G.profile(G.getUnit(state)).M*(mode==='march'?2:1);else if(value==='back'||value==='side')distance=G.profile(G.getUnit(state)).M/2;else if(kind==='wheel'){angle=15;distance=0;}else{angle=90;distance=0;mode='advance';}refreshPreview();};
$('reformMode').onclick=()=>$('pivotKind').click();$('sideLeft').onclick=()=>{side=-1;refreshPreview();};$('sideRight').onclick=()=>{side=1;refreshPreview();};
