function showUnitTooltip(group){if(!group||drag||ordersOpen)return;const u=G.getUnit(state,group.dataset.unit);if(!u)return;const tip=$('unitTooltip'),keys=['M','WS','BS','S','T','W','I','A','Ld'],p=G.profile(u),f=G.FACTIONS[u.faction];tip.innerHTML=`<div class="tooltip-title">${u.name}</div><div class="tooltip-meta">${u.id} · ${armyName(u.team)} · ${u.role==='wizard'?u.wounds+'/2 W':G.aliveCount(u)+'/20 surviving'} · ${doneLabel(u)}</div><table aria-label="Unit characteristics"><thead><tr>${keys.map(k=>'<th scope="col">'+k+'</th>').join('')}</tr></thead><tbody><tr>${keys.map(k=>'<td>'+p[k]+'</td>').join('')}</tr></tbody></table><p><b>Armour: ${p.save}+</b> · ${G.equipment(u)}<br>${f.base} × ${f.base} mm base${u.role==='wizard'?'':'s · 5 files × 4 ranks'}<br>Click for orders.</p>`;tip.hidden=false;group.setAttribute('aria-describedby','unitTooltip');const bounds=group.getBoundingClientRect(),box=tip.getBoundingClientRect();const left=Math.max(8,Math.min(innerWidth-box.width-8,bounds.left+bounds.width/2-box.width/2));let top=bounds.top-box.height-12;if(top<8)top=bounds.bottom+12;tip.style.left=left+'px';tip.style.top=Math.max(8,Math.min(innerHeight-box.height-8,top))+'px';}
